// Una máquina virtual de pila en 30 líneas. El «bytecode» es un arreglo de instrucciones.
const programa = [
  ["PUSH", 0], ["STORE", "total"],          //  0-1: total = 0
  ["PUSH", 1], ["STORE", "i"],              //  2-3: i = 1
  ["LOAD", "i"], ["LOAD", "n"], ["GT"],     //  4-6: ¿i > n?
  ["JMPIF", 17],                            //  7:   si es verdad, salir del bucle
  ["LOAD", "total"], ["LOAD", "i"], ["ADD"], ["STORE", "total"],   //  8-11: total = total + i
  ["LOAD", "i"], ["PUSH", 1], ["ADD"], ["STORE", "i"],             // 12-15: i = i + 1
  ["JMP", 4],                               // 16:  volver a preguntar
  ["LOAD", "total"], ["PRINT"], ["HALT"],   // 17-19
];

function ejecutar(codigo, variables, mostrar = false) {
  const pila = [];
  let pc = 0, pasos = 0, salida = null;
  while (true) {
    const [op, arg] = codigo[pc];
    pasos++;
    if (mostrar && pasos <= 12) console.log(`pc=${String(pc).padStart(2)} ${op.padEnd(5)} ${arg ?? ""}`.padEnd(24) + `pila=[${pila}]`);
    pc++;
    switch (op) {
      case "PUSH":  pila.push(arg); break;
      case "LOAD":  pila.push(variables[arg]); break;
      case "STORE": variables[arg] = pila.pop(); break;
      case "ADD":   { const b = pila.pop(), a = pila.pop(); pila.push(a + b); break; }
      case "GT":    { const b = pila.pop(), a = pila.pop(); pila.push(a > b); break; }
      case "JMP":   pc = arg; break;
      case "JMPIF": if (pila.pop()) pc = arg; break;
      case "PRINT": salida = pila.pop(); break;
      case "HALT":  return { salida, pasos };
    }
  }
}

console.log(ejecutar(programa, { n: 4 }, true));

const n = 100_000;
let t0 = performance.now();
const r = ejecutar(programa, { n });
const tVM = performance.now() - t0;
t0 = performance.now();
let total = 0; for (let i = 1; i <= n; i++) total += i;
const tDirecto = performance.now() - t0;
console.log(`n=${n}: la VM ejecutó ${r.pasos.toLocaleString("es-AR")} instrucciones de bytecode, resultado ${r.salida}`);
console.log(`VM de juguete: ${tVM.toFixed(1)} ms · bucle directo de JS: ${tDirecto.toFixed(2)} ms · resultado ${total}`);

// Diez lotes seguidos del mismo trabajo: un millón de llamadas a una función chica.
function paso(h, i) {
  return (h * 31 + i) | 0;
}
function lote(n) {
  let h = 0;
  for (let i = 0; i < n; i++) h = paso(h, i);
  return h;
}

const tiempos = [];
let resultado = 0;
for (let k = 1; k <= 10; k++) {
  const t0 = performance.now();
  resultado ^= lote(1_000_000);
  tiempos.push(performance.now() - t0);
}
tiempos.forEach((t, k) => console.log(`lote ${k + 1}: ${t.toFixed(2)} ms`));
console.log("resultado", resultado, "(se usa para que el trabajo no se pueda descartar)");
